+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+const { cal } = ChromeUtils.importESModule(
+  "resource:///modules/calendar/calUtils.sys.mjs"
+);
+
+/**
+ * Plain display data for a category.
+ *
+ * @typedef {object} CalendarEventCategoryOption
+ * @property {string} name - The category name.
+ * @property {string} color - The background color, or an empty string.
+ * @property {string} textColor - The contrasting text color, or an empty string.
+ */
+
+/**
+ * Returns a category's configured colors without changing preferences.
+ *
+ * @param {string} categoryName - The category name.
+ * @param {string} [fallback=""] - The color used when no color is configured.
+ * @returns {CalendarEventCategoryOption} The name and usable colors.
+ */
+export function getCategoryOption(categoryName, fallback = "") {
+  const key = cal.view.formatStringForCSSRule(categoryName);
+  const color = Services.prefs.getStringPref(
+    `calendar.category.color.${key}`,
+    fallback
+  );
+  // The Calendar contrast helper accepts six-digit RGB colors only.
+  const usableColor = /^#[0-9a-f]{6}$/i.test(color) ? color : "";
+
+  return {
+    name: categoryName,
+    color: usableColor,
+    textColor: usableColor ? cal.view.getContrastingTextColor(usableColor) : "",
+  };
+}
+
+/**
+ * Returns available names and colors without initializing category preferences.
+ * Unset or empty names use the localized defaults, as cal.category.fromPrefs()
+ * does. Selected event categories are loaded separately.
+ *
+ * @returns {Promise<CalendarEventCategoryOption[]>} The sorted category choices.
+ */
+export async function loadCategoryOptions() {
+  const configuredNames = Services.prefs.getStringPref(
+    "calendar.categories.names",
+    null
+  );
+
+  // fromPrefs() initializes default preferences. Parse names directly so
+  // opening a draft cannot write category settings.
+  const names = cal.category.stringToArray(
+    configuredNames ||
+      (await new Localization(["calendar/categories.ftl"]).formatValue(
+        "categories2"
+      ))
+  );
+
+  return [...new Set(names)]
+    .sort(new Intl.Collator().compare)
+    .map(categoryName =>
+      getCategoryOption(
+        categoryName,
+        !configuredNames ? cal.view.hashColor(categoryName) : ""
+      )
+    );
+}
