+  /**
+   * Binds category controls to a route before its values load.
+   *
+   * @param {CalendarEventDialogRouteRequest} route - The owning route.
+   */
+  #startCategories(route) {
+    this.#categoryRoute = route;
+
+    const oldButton = this.querySelector(".calendar-event-add-category");
+    const button = oldButton.cloneNode(true);
+
+    oldButton.replaceWith(button);
+    button.setAttribute("aria-expanded", "false");
+
+    button.addEventListener("click", () => {
+      if (!route.isCurrent()) {
+        return;
+      }
+
+      this.#setCategoryPopup(
+        this.#categoryPopup == "choices" ? null : "choices"
+      );
+    });
+  }
+
+  /**
+   * Changes only the current route's category section.
+   *
+   * @param {CalendarEventDialogRouteRequest} route - The control's owning route.
+   * @param {string} categoryName - The category to add or remove.
+   * @param {boolean} selected - Whether to select the category.
+   */
+  #changeCategory(route, categoryName, selected) {
+    if (
+      !route.isCurrent() ||
+      this.#categoryRoute !== route ||
+      !this.#draft ||
+      this.#createEditSession?.operation.status == "pending" ||
+      this.#categories.includes(categoryName) == selected
+    ) {
+      return;
+    }
+
+    const categories = selected
+      ? [...this.#categories, categoryName]
+      : this.#categories.filter(category => category != categoryName);
+
+    this.updateDraftSection("categories", { categories });
+  }
+
+  /**
+   * Builds and translates a category display before replacing the current one.
+   * Discards translation results from older selections or routes.
+   *
+   * @returns {Promise<void>} Resolves after rendering or discarding a stale render.
+   */
+  async #renderCategories() {
+    const route = this.#categoryRoute;
+
+    if (!route?.isCurrent()) {
+      return;
+    }
+
+    const renderId = ++this.#categoryRenderId;
+    const names = this.#categories;
+    const fragment = document.createDocumentFragment();
+    const template = this.querySelector(
+      ".calendar-event-category-chip-template"
+    );
+    const focused = document.activeElement;
+    const focusedName = focused?.closest("[data-category]")?.dataset.category;
+    const focusedChoice = focused?.closest(".calendar-event-category-choices");
+    const focusedIndex = names.indexOf(focusedName);
+
+    const previousIndex = this.#categoryChips.findIndex(chip =>
+      chip.contains(focused)
+    );
+
+    const chips = names.map(categoryName => {
+      const chip = template.content.firstElementChild.cloneNode(true);
+      const label = chip.querySelector(".calendar-event-category-label");
+      const button = chip.querySelector("button");
+      const option =
+        this.#categoryOptions.find(item => item.name == categoryName) ??
+        getCategoryOption(categoryName);
+
+      chip.dataset.category = categoryName;
+      label.textContent = categoryName;
+      label.title = categoryName;
+      chip.style.setProperty("--item-color", option.color);
+      chip.style.setProperty("--item-text-color", option.textColor);
+
+      document.l10n.setAttributes(button, "calendar-event-remove-category", {
+        category: categoryName,
+      });
+
+      button.addEventListener("click", () =>
+        this.#changeCategory(route, categoryName, false)
+      );
+
+      return chip;
+    });
+
+    const choices = [
+      ...new Set([
+        ...this.#categoryOptions.map(option => option.name),
+        ...names,
+      ]),
+    ]
+      .sort(new Intl.Collator().compare)
+      .map(categoryName => {
+        const item = document.createElement("li");
+        const label = document.createElement("label");
+        const input = document.createElement("input");
+
+        input.type = "checkbox";
+        input.checked = names.includes(categoryName);
+        input.dataset.category = categoryName;
+
+        input.addEventListener("change", () => {
+          this.#changeCategory(route, categoryName, input.checked);
+
+          if (route.isCurrent()) {
+            input.checked = this.#categories.includes(categoryName);
+          }
+        });
+
+        label.append(input, document.createTextNode(categoryName));
+        item.append(label);
+
+        return item;
+      });
+
+    // Translate both counts now so hidden layout can choose a capacity
+    // synchronously before the dialog is positioned.
+    const moreButtons = [2, 3].map(capacity => {
+      const button = this.querySelector(
+        ".calendar-event-more-categories"
+      ).cloneNode(false);
+
+      button.type = "button";
+      button.hidden = names.length <= capacity;
+
+      document.l10n.setAttributes(button, "calendar-event-more-categories", {
+        count: Math.max(0, names.length - capacity),
+      });
+
+      button.addEventListener("click", () => {
+        if (route.isCurrent()) {
+          this.#setCategoryPopup(
+            this.#categoryPopup == "overflow" ? null : "overflow"
+          );
+        }
+      });
+
+      return button;
+    });
+
+    fragment.append(...chips, ...choices, ...moreButtons);
+    await document.l10n.translateFragment(fragment);
+
+    if (!route.isCurrent() || renderId !== this.#categoryRenderId) {
+      return;
+    }
+
+    const restoreFocus = this.open && focused === document.activeElement;
+
+    this.#categoryChips = chips;
+    this.#categoryMoreButtons = moreButtons;
+    this.querySelector(".calendar-event-category-choices").replaceChildren(
+      ...choices
+    );
+    this.querySelector(".calendar-event-add-category").disabled =
+      !choices.length;
+    this.#layoutCategories();
+    this.#setCategoryPopup(this.#categoryPopup);
+
+    if (!restoreFocus || (!focusedName && previousIndex == -1)) {
+      return;
+    }
+
+    if (focusedChoice) {
+      const input = choices
+        .map(item => item.querySelector("input"))
+        .find(choice => choice.dataset.category == focusedName);
+
+      (input ?? this.querySelector(".calendar-event-add-category")).focus();
+
+      return;
+    }
+
+    const index =
+      focusedIndex == -1
+        ? Math.min(previousIndex, chips.length - 1)
+        : focusedIndex;
+    const chip = chips[index];
+    const overflow = this.querySelector(".calendar-event-category-overflow");
+    const target =
+      chip && (!overflow.contains(chip) || !overflow.hidden)
+        ? chip.querySelector("button")
+        : this.querySelector(".calendar-event-add-category");
+
+    target.focus();
+  }
+
+  /**
+   * Measures category capacity before the base dialog sets its position.
+   */
+  prepareLayout() {
+    this.#layoutCategories();
+  }
+
+  /**
+   * Shows two or three chips and moves the remainder into the bounded list.
+   * Measures full labels before allowing the visible chips to shrink.
+   */
+  #layoutCategories() {
+    if (!this.#categoryMoreButtons.length) {
+      return;
+    }
+
+    const list = this.querySelector(".calendar-event-category-list");
+
+    // A closed dialog or collapsed row has no usable width. The layout hook runs
+    // when the dialog opens. The resize observer runs when the row expands.
+    if (!list.clientWidth) {
+      return;
+    }
+
+    const overflow = this.querySelector(".calendar-event-category-overflow");
+    const chips = this.#categoryChips;
+    const candidate = this.#categoryMoreButtons[1];
+    const currentMore = this.querySelector(".calendar-event-more-categories");
+    const focused = document.activeElement;
+    const candidates = chips.slice(0, 3);
+
+    // The base dialog opens invisibly before the first measurement.
+    currentMore.replaceWith(candidate);
+    list.replaceChildren(...candidates);
+
+    for (const chip of candidates) {
+      chip.style.flexShrink = "0";
+    }
+
+    const gap = parseFloat(getComputedStyle(list).columnGap) || 0;
+    const required =
+      candidates.reduce(
+        (width, chip) => width + chip.getBoundingClientRect().width,
+        0
+      ) +
+      Math.max(0, candidates.length - 1) * gap;
+    const capacity = list.clientWidth && required > list.clientWidth ? 2 : 3;
+
+    for (const chip of candidates) {
+      chip.style.removeProperty("flex-shrink");
+    }
+
+    list.replaceChildren(...chips.slice(0, capacity));
+    overflow.replaceChildren(...chips.slice(capacity));
+    candidate.replaceWith(this.#categoryMoreButtons[capacity - 2]);
+    this.#setCategoryPopup(this.#categoryPopup);
+
+    if (
+      !this.open ||
+      !focused?.matches(
+        ".calendar-event-remove-category, .calendar-event-more-categories"
+      )
+    ) {
+      return;
+    }
+
+    if (overflow.contains(focused) && overflow.hidden) {
+      this.querySelector(".calendar-event-more-categories").focus();
+    } else if (focused.isConnected) {
+      focused.focus();
+    } else if (focused.matches(".calendar-event-more-categories")) {
+      const more = this.querySelector(".calendar-event-more-categories");
+
+      (more.hidden
+        ? this.querySelector(".calendar-event-add-category")
+        : more
+      ).focus();
+    }
+  }
+
+  /**
+   * Opens one category list and updates its disclosure button.
+   *
+   * @param {"choices"|"overflow"|null} popup - The list to open, or null to close.
+   */
+  #setCategoryPopup(popup) {
+    const choices = this.querySelector(".calendar-event-category-choices");
+    const overflow = this.querySelector(".calendar-event-category-overflow");
+    const add = this.querySelector(".calendar-event-add-category");
+    const more = this.querySelector(".calendar-event-more-categories");
+
+    if (!choices || !overflow) {
+      return;
+    }
+
+    this.#categoryPopup =
+      popup == "overflow" && !overflow.childElementCount ? null : popup;
+    choices.hidden = this.#categoryPopup != "choices";
+    overflow.hidden = this.#categoryPopup != "overflow";
+    add.setAttribute("aria-expanded", String(!choices.hidden));
+    more.setAttribute("aria-expanded", String(!overflow.hidden));
+  }
+
+  /**
+   * Closes category lists with Escape and moves among choices with arrow keys.
+   *
+   * @param {KeyboardEvent} event - The dialog keyboard event.
+   */
+  #handleCategoryKey(event) {
+    if (!this.#categoryPopup) {
+      return;
+    }
+
+    if (event.key == "Escape") {
+      event.preventDefault();
+      event.stopPropagation();
+
+      const selector =
+        this.#categoryPopup == "choices"
+          ? ".calendar-event-add-category"
+          : ".calendar-event-more-categories";
+
+      this.#setCategoryPopup(null);
+      this.querySelector(selector).focus();
+
+      return;
+    }
+
+    const choices = [
+      ...this.querySelectorAll(".calendar-event-category-choices input"),
+    ];
+    const index = choices.indexOf(event.target);
+
+    if (
+      index == -1 ||
+      !["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)
+    ) {
+      return;
+    }
+
+    event.preventDefault();
+
+    let next =
+      (index + (event.key == "ArrowDown" ? 1 : -1) + choices.length) %
+      choices.length;
+
+    if (event.key == "Home") {
+      next = 0;
+    } else if (event.key == "End") {
+      next = choices.length - 1;
+    }
+
+    choices[next].focus();
+  }
+
