+add_task(async function test_thumbStaysInsideTrack() {
+  const row = contentDocument.querySelector("calendar-dialog-toggleable-row");
+  const checkbox = getCheckbox(row);
+  const originalDirection = contentDocument.documentElement.dir;
+
+  // Disable motion so the check measures the final thumb position.
+  await SpecialPowers.pushPrefEnv({
+    set: [["ui.prefersReducedMotion", 1]],
+  });
+  await TestUtils.waitForCondition(
+    () => contentWindow.matchMedia("(prefers-reduced-motion: reduce)").matches,
+    "The switch geometry check should use reduced motion"
+  );
+
+  for (const direction of ["ltr", "rtl"]) {
+    contentDocument.documentElement.dir = direction;
+
+    for (const small of [false, true]) {
+      checkbox.classList.toggle("toggle-checkbox-sm", small);
+
+      for (const checked of [false, true]) {
+        row.toggleAttribute("checked", checked);
+
+        const thumb = contentWindow.getComputedStyle(checkbox, "::before");
+        const width = parseFloat(thumb.width);
+        const margin = parseFloat(thumb.marginInlineStart);
+        const translation = parseFloat(thumb.translate) || 0;
+
+        // The thumb starts at the right edge when text runs from right to left.
+        const start =
+          direction == "rtl" ? checkbox.clientWidth - width - margin : margin;
+        const left = start + translation;
+        const state = `${direction}, ${small ? "small" : "normal"}, ${
+          checked ? "checked" : "unchecked"
+        }`;
+
+        Assert.greaterOrEqual(
+          left,
+          0,
+          `The ${state} thumb should stay inside the left track edge`
+        );
+        Assert.lessOrEqual(
+          left + width,
+          checkbox.clientWidth,
+          `The ${state} thumb should stay inside the right track edge`
+        );
+      }
+    }
+  }
+
+  contentDocument.documentElement.dir = originalDirection;
+  checkbox.classList.remove("toggle-checkbox-sm");
+  row.removeAttribute("checked");
+});
